// static waxi_dlr_variant_t memory_map = WAXI_INVALID_HOST_DATA_HANDLE;
static State state = NONE;

sys_machine_input_t sys_machine_in = INIT_SYS_MACHINE_INPUT();

// For Pit Pendulum, changed from P2 to P1
